// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import {
  additionsKey,
  parseNTriplesTerm,
  statementBinding,
  statementsQuery,
  takeAdditions,
} from "../../../main/frontend/graph-explorer/graph-additions.ts";

function memoryStorage(initial = {}) {
  const values = new Map(Object.entries(initial));
  return {
    getItem: (key) => (values.has(key) ? values.get(key) : null),
    setItem: (key, value) => values.set(key, String(value)),
    removeItem: (key) => values.delete(key),
    values,
  };
}

test("the queue key matches the Workbench pages' (scripts/ts/graphAdditions.ts)", () => {
  assert.equal(
    additionsKey("/wb/", "my repo", "server"),
    'rdf4j-workbench-graph-additions:["repository-v2","/wb","server","my repo"]',
  );
});

test("the Graph page takes the queued additions once and drops malformed ones", () => {
  const key = additionsKey("/wb", "repo", "server");
  const storage = memoryStorage({
    [key]: JSON.stringify([
      { kind: "resource", term: "<urn:a>" },
      { kind: "statement", subject: "<urn:a>", predicate: "<urn:p>", object: '"x"@en' },
      { kind: "query", query: "CONSTRUCT WHERE { ?s ?p ?o }" },
      { kind: "resource", term: "nonsense" },
      { kind: "other" },
    ]),
  });
  assert.deepEqual(takeAdditions("/wb", "repo", storage, "server").map((entry) => entry.kind), ["resource", "statement", "query"]);
  assert.equal(storage.getItem(key), null);
  assert.deepEqual(takeAdditions("/wb", "repo", storage, "server"), []);
  assert.deepEqual(takeAdditions("/wb", "repo", memoryStorage({ [key]: "{broken" }), "server"), []);
});

test("N-Triples terms become SPARQL JSON terms", () => {
  assert.deepEqual(parseNTriplesTerm("<http://example.org/a\\u00E9>"), { type: "uri", value: "http://example.org/aé" });
  assert.deepEqual(parseNTriplesTerm("_:b12"), { type: "bnode", value: "b12" });
  assert.deepEqual(parseNTriplesTerm('"line\\nbreak \\"quoted\\""'), { type: "literal", value: 'line\nbreak "quoted"' });
  assert.deepEqual(parseNTriplesTerm('"Hallo"@de'), { type: "literal", value: "Hallo", "xml:lang": "de" });
  assert.deepEqual(parseNTriplesTerm('"مرحبا"@ar--rtl'), {
    type: "literal",
    value: "مرحبا",
    "xml:lang": "ar",
    "its:dir": "rtl",
  });
  assert.deepEqual(parseNTriplesTerm('"39"^^<http://www.w3.org/2001/XMLSchema#integer>'), {
    type: "literal",
    value: "39",
    datatype: "http://www.w3.org/2001/XMLSchema#integer",
  });
  assert.equal(parseNTriplesTerm("<<( <urn:a> <urn:p> <urn:b> )>>"), null, "triple terms are not drawn");
  assert.equal(parseNTriplesTerm("plain"), null);
});

test("a queued statement reads as one ?source ?predicate ?target row", () => {
  assert.deepEqual(statementBinding({ kind: "statement", subject: "<urn:a>", predicate: "<urn:p>", object: '"x"' }), {
    source: { type: "uri", value: "urn:a" },
    predicate: { type: "uri", value: "urn:p" },
    target: { type: "literal", value: "x" },
  });
  assert.equal(statementBinding({ kind: "statement", subject: '"x"', predicate: "<urn:p>", object: "<urn:b>" }), null);
});

test("queued statements are recorded as a query that answers them again", () => {
  assert.equal(
    statementsQuery([
      { kind: "statement", subject: "<urn:a>", predicate: "<urn:p>", object: '"x\\ny"@en' },
      { kind: "statement", subject: "_:b1", predicate: "<urn:p>", object: "<urn:b>" },
    ]),
    'SELECT ?source ?predicate ?target WHERE { VALUES (?source ?predicate ?target) {\n  (<urn:a> <urn:p> "x\\ny"@en)\n} }',
    "blank nodes cannot be written in VALUES, so their statements are left out",
  );
  assert.equal(statementsQuery([{ kind: "statement", subject: "_:b1", predicate: "<urn:p>", object: "<urn:b>" }]), "");
});

import { returnAdditions } from "../../../main/frontend/graph-explorer/graph-additions.ts";

test("additions that could not be applied go back to the front of the queue", () => {
  const key = additionsKey("/wb", "repo", "server");
  const storage = memoryStorage({ [key]: JSON.stringify([{ kind: "resource", term: "<urn:later>" }]) });
  returnAdditions("/wb", "repo", [{ kind: "resource", term: "<urn:first>" }, { kind: "query", query: "CONSTRUCT WHERE { ?s ?p ?o }" }], storage, "server");
  assert.deepEqual(
    takeAdditions("/wb", "repo", storage, "server").map((entry) => entry.term ?? entry.query),
    ["<urn:first>", "CONSTRUCT WHERE { ?s ?p ?o }", "<urn:later>"],
  );
  returnAdditions("/wb", "repo", [], storage, "server");
  assert.equal(storage.getItem(key), null, "nothing to return writes nothing");
});

test("escapes that name no Unicode scalar value make the term malformed instead of throwing", () => {
  for (const term of [
    '"x\\UFFFFFFFF"',
    '"\\U00110000"',
    '"\\uD800"',
    '"\\uDFFF tail"',
    "<urn:\\U00110000>",
    "<urn:\\uDBFF>",
    '"x"^^<urn:\\U0011FFFF>',
    '"x"@en--ltr\\U00110000',
  ]) {
    assert.doesNotThrow(() => parseNTriplesTerm(term), term);
    assert.equal(parseNTriplesTerm(term), null, term);
  }
});

test("escapes up to the last scalar value still decode", () => {
  assert.deepEqual(parseNTriplesTerm('"\\U0001F600"'), { type: "literal", value: "😀" });
  assert.deepEqual(parseNTriplesTerm('"\\U0010FFFF"'), { type: "literal", value: String.fromCodePoint(0x10ffff) });
  assert.deepEqual(parseNTriplesTerm('"\\uD7FF\\uE000"'), { type: "literal", value: "퟿" });
  assert.deepEqual(parseNTriplesTerm("<urn:a\\u0062>"), { type: "uri", value: "urn:ab" });
  assert.deepEqual(parseNTriplesTerm('"x"^^<urn:t\\u0079pe>'), { type: "literal", value: "x", datatype: "urn:type" });
});

test("one malformed queued entry is dropped without losing the rest of the queue", () => {
  const key = additionsKey("/wb", "repo", "server");
  const storage = memoryStorage({
    [key]: JSON.stringify([
      { kind: "resource", term: "<urn:first>" },
      { kind: "resource", term: '"\\UFFFFFFFF"' },
      { kind: "statement", subject: "<urn:a>", predicate: "<urn:p>", object: '"bad \\U00110000"' },
      { kind: "statement", subject: "<urn:a>", predicate: "<urn:p\\uD800>", object: "<urn:b>" },
      { kind: "query", query: "CONSTRUCT WHERE { ?s ?p ?o }" },
      { kind: "resource", term: "<urn:last>" },
    ]),
  });

  const taken = takeAdditions("/wb", "repo", storage, "server");

  assert.deepEqual(taken.map((entry) => entry.term ?? entry.query), ["<urn:first>", "CONSTRUCT WHERE { ?s ?p ?o }", "<urn:last>"]);
  assert.equal(storage.getItem(key), null, "the queue is taken once");
});

test("handing additions back never throws on a malformed entry already in the queue", () => {
  const key = additionsKey("/wb", "repo", "server");
  const storage = memoryStorage({ [key]: JSON.stringify([{ kind: "resource", term: '"\\UFFFFFFFF"' }, { kind: "resource", term: "<urn:kept>" }]) });

  assert.doesNotThrow(() => returnAdditions("/wb", "repo", [{ kind: "resource", term: "<urn:back>" }], storage, "server"));
  assert.deepEqual(takeAdditions("/wb", "repo", storage, "server").map((entry) => entry.term), ["<urn:back>", "<urn:kept>"]);
});
